templates.jenkins:
sh '''
    npm install -g snyk
    snyk auth ${SNYK_TOKEN}
    snyk test --severity-threshold=${SNYK_SEVERITY_THRESHOLD:-high} --sarif-file-output=snyk.sarif || ${SNYK_FAIL_ON_ISSUES:-true}
'''
archiveArtifacts artifacts: 'snyk.sarif', allowEmptyArchive: true

templates.circleci:
npm install -g snyk
snyk auth $SNYK_TOKEN
snyk test --severity-threshold=${SNYK_SEVERITY_THRESHOLD:-high} --sarif-file-output=snyk.sarif || ${SNYK_FAIL_ON_ISSUES:-true}

templates.github_actions:
- name: Run Gitleaks secret scan
  uses: gitleaks/gitleaks-action@v2
  env:
    GITLEAKS_LICENSE: ${{ secrets.GITLEAKS_LICENSE }}
    GITLEAKS_CONFIG: ${{ vars.GITLEAKS_CONFIG_PATH || '.gitleaks.toml' }}

- name: Send Microsoft Teams Notification
  run: |
    STATUS="${{ needs.deploy.result == 'success' && 'SUCCESS' || 'FAILED' }}"
    COLOR="${{ needs.deploy.result == 'success' && '28a745' || 'd93025' }}"
    curl -X POST -H 'Content-Type: application/json' \
      -d "{
        \"@type\": \"MessageCard\",
        \"@context\": \"http://schema.org/extensions\",
        \"themeColor\": \"${COLOR}\",
        \"summary\": \"Pipeline ${STATUS}\",
        \"sections\": [{
          \"activityTitle\": \"Pipeline ${STATUS}\",
          \"facts\": [
            { \"name\": \"Repository\", \"value\": \"${{ github.repository }}\" },
            { \"name\": \"Branch\", \"value\": \"${{ github.ref_name }}\" },
            { \"name\": \"Commit\", \"value\": \"${{ github.sha }}\" },
            { \"name\": \"Run\", \"value\": \"#${{ github.run_number }}\" }
          ],
          \"markdown\": true
        }],
        \"potentialAction\": [{
          \"@type\": \"OpenUri\",
          \"name\": \"View Run\",
          \"targets\": [{ \"os\": \"default\", \"uri\": \"${{ github.server_url }}/${{ github.repository }}/actions/runs/${{ github.run_id }}\" }]
        }]
      }" ${{ secrets.TEAMS_WEBHOOK_URL }}

