templates.jenkins:
withAWS(region: "${AWS_REGION}", credentials: 'aws-credentials-id') {
    sh '''
        zip -r function.zip . -x '*.git*'
        aws lambda update-function-code --function-name ${LAMBDA_FUNCTION_NAME} --zip-file fileb://function.zip --region ${AWS_REGION}
        aws lambda wait function-updated --function-name ${LAMBDA_FUNCTION_NAME} --region ${AWS_REGION}
        aws lambda invoke --function-name ${LAMBDA_FUNCTION_NAME} --payload '{}' /tmp/response.json --region ${AWS_REGION}
        cat /tmp/response.json
    '''
}

templates.github_actions:
- name: Azure Login via OIDC
  uses: azure/login@v2
  with:
    client-id: ${{ secrets.AZURE_CLIENT_ID }}
    tenant-id: ${{ secrets.AZURE_TENANT_ID }}
    subscription-id: ${{ secrets.AZURE_SUBSCRIPTION_ID }}
- name: Deploy to Azure Functions
  uses: azure/functions-action@v1
  with:
    app-name: ${{ secrets.AZURE_FUNCTIONAPP_NAME }}
    package: ${{ vars.FUNCTIONAPP_PACKAGE_PATH || '.' }}
- name: Verify Azure Functions deployment
  run: |
    curl -sf -o /dev/null -w '%{http_code}' "https://${{ secrets.AZURE_FUNCTIONAPP_NAME }}.azurewebsites.net/api/health" || echo 'Health check failed'
